WITH filtered AS (SELECT *, REPLACE(full_name, ' ', '_') AS full_name_slug FROM employees WHERE manager_id IS NOT NULL) SELECT id, full_name, email, manager_id, salary, hire_date, level, full_name_slug, LAST_VALUE(level, TRUE) OVER (PARTITION BY job_title ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_level, AVG(salary) OVER (ORDER BY salary ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS salary_avg_2_prior FROM filtered;
